<script setup lang="ts">
import{patientCommand,parsePatientCommand,samePatientCommand}from'./patient-command';
import{patientPendingStatusPath,validPatientStatus}from'./patient-pending-status';
import{ref,computed,onMounted,watch}from'vue';import{useSalesScope}from'./use-sales-scope';import{Users,Search,Plus,X,History,Save,ShieldCheck}from'@lucide/vue';
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized']);const clinics=ref<any[]>([]),clinic=ref(''),query=ref(''),rows=ref<any[]>([]),nextId=ref<string|null>(null),detail=ref<any>(null),history=ref<any[]>([]),nextVersion=ref<string|null>(null),busy=ref(false),error=ref(''),notice=ref(''),branch=ref(''),data=ref<any>({}),reason=ref(''),preview=ref<any>(null),checked=ref(false),pending=ref<any>(null);
const names:any={identity:'基本资料',source:'患者来源',contact:'联系要求与渠道',health:'过敏信息',tags:'患者标签'},knowledge:any={unknown:'尚未了解',none_reported:'患者表示无已知过敏',reported:'已报告具体过敏'},labels:any={name:'姓名',birthDate:'出生日期',phone:'联系电话',contactAddress:'联系地址',billingAddress:'账单地址',email:'电子邮箱',sourceNote:'患者来源',introducerNote:'介绍人说明',contactPreference:'联系要求',channels:'沟通渠道',knowledge:'过敏了解状态',note:'过敏备注',allergies:'逐项过敏信息',tags:'标签'},cache=()=> 'adc.patientPending:'+props.staff?.accountId;
const directoryTotal=ref<number|null>(null),directoryAsOf=ref(''),historyTotal=ref<number|null>(null),historyAsOf=ref('');
function clearDirectory(){rows.value=[];nextId.value=null;loadedQuery.value=null;directoryTotal.value=null;directoryAsOf.value='';}
function clearHistory(){history.value=[];nextVersion.value=null;historyTotal.value=null;historyAsOf.value='';}
const selection=ref(0);const identity=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId]),authScope=useSalesScope(identity),viewScope=useSalesScope(()=>JSON.stringify([identity(),clinic.value,query.value,selection.value])),loadedQuery=ref<string|null>(null);
function clearView(){detail.value=null;clearHistory();branch.value='';data.value={};reason.value='';preview.value=null;checked.value=false;}
watch(()=>JSON.stringify([clinic.value,query.value]),()=>{clearDirectory();clearView();busy.value=false;},{flush:'sync'});
watch(()=>JSON.stringify([branch.value,data.value,reason.value]),()=>{checked.value=false;},{flush:'sync'});
async function api(path:string,body?:any,current:()=>boolean=()=>true){const own=authScope.capture(),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api/v1/patients'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:controller.signal}),v=await r.json().catch(()=>({}));if(!r.ok){if(own()&&current()&&(r.status===401||r.status===403)){clearView();clearDirectory();if(r.status===401)emit('unauthorized');}throw Object.assign(Error(v.message||'档案办理未完成。'),{status:r.status});}return v;}finally{clearTimeout(timer);}}
function addChannel(){data.value.channels.push({id:crypto.randomUUID(),name:'',note:''});}
function addAllergy(){data.value.allergies.push({id:crypto.randomUUID(),allergen:'',description:''});}
const cacheBlocked=ref(false),cacheError=ref('');
const commandStatus=ref<any>(null),commandBusy=ref(false),retryChecked=ref(false);
function restoreCache(){cacheBlocked.value=false;cacheError.value='';pending.value=null;try{const raw=sessionStorage.getItem(cache());if(raw)pending.value=parsePatientCommand(raw,props.staff);}catch{cacheBlocked.value=true;cacheError.value='原提交缓存损坏、身份不匹配或无法读取；请保留记录核查，未发送新保存。';}}
function cleanupKnown(){const p=pending.value;if(!p||!['confirmed','rejected'].includes(p.phase)||busy.value)return false;try{const original=patientCommand(p,props.staff),raw=sessionStorage.getItem(cache());if(raw&&!samePatientCommand(parsePatientCommand(raw,props.staff),original))throw Error('本机存在另一笔原请求，未清理。');sessionStorage.removeItem(cache());pending.value=null;cacheError.value='';return true;}catch(e:any){cacheError.value=e.message||'本机提示未清理，请仅清理提示，不要重新办理。';return false;}}
function markKnown(p:any,phase:string){pending.value={...p,phase};try{keep();}catch{cacheError.value='已收到明确结果，但本机状态未写入；请清理提示，不要重办。';}}

watch(()=>JSON.stringify([identity(),pending.value]),()=>{commandStatus.value=null;commandBusy.value=false;retryChecked.value=false;},{flush:'sync'});
async function checkPending(){let p:any;if(!pending.value||busy.value||commandBusy.value||cacheBlocked.value)return;try{p=patientCommand(pending.value,props.staff);if(p.phase!=='pending')return;}catch(e:any){cacheBlocked.value=true;cacheError.value=e.message;return;}const current=authScope.begin('pending-status',()=>JSON.stringify(pending.value));commandBusy.value=true;error.value='';commandStatus.value=null;retryChecked.value=false;try{const r=await api(patientPendingStatusPath(p),undefined,current);if(current())commandStatus.value=validPatientStatus(p,r);}catch(e:any){if(current())error.value=e.message;}finally{if(current.active())commandBusy.value=false;}}
function clearPending(){const p=pending.value;if(!p||busy.value||commandBusy.value||commandStatus.value?.state!=='completed')return;try{validPatientStatus(p,commandStatus.value);markKnown(patientCommand(p,props.staff),'confirmed');if(cleanupKnown()){branch.value='';preview.value=null;notice.value='原保存结果已核对，仅清理本机提示。';}}catch(e:any){error.value=e.message;}}

async function retryPending(){if(!pending.value||!retryChecked.value||commandStatus.value?.state!=='not_found')return;try{validPatientStatus(pending.value,commandStatus.value);}catch(e:any){error.value=e.message;return;}const p=pending.value;commandStatus.value=null;retryChecked.value=false;await submit(p,true);}
function keep(){if(!pending.value)return;const p=patientCommand(pending.value,props.staff),raw=sessionStorage.getItem(cache());if(raw&&!samePatientCommand(parsePatientCommand(raw,props.staff),p))throw Error('本机原记录已变化，未覆盖其他请求。');sessionStorage.setItem(cache(),JSON.stringify(p));}
async function refresh(more=false){if(more&&(!nextId.value||loadedQuery.value!==query.value))return;if(!more)selection.value++;const current=viewScope.begin('list',()=>query.value);busy.value=true;error.value='';if(!more){clearDirectory();clearView();}try{const r=await api('/directory?clinicId='+clinic.value+'&q='+encodeURIComponent(query.value)+(more?'&cursor='+encodeURIComponent(nextId.value!):''),undefined,current);if(!current())return;if(more&&r.asOf!==directoryAsOf.value)throw Object.assign(Error('患者目录读取时点已变化，请重新查询。'),{status:409});rows.value=more?[...rows.value,...r.items]:r.items;nextId.value=r.next;directoryTotal.value=r.total;directoryAsOf.value=r.asOf;loadedQuery.value=query.value;}catch(e:any){if(current()){error.value=e.message;if([401,403,409].includes(e.status)){clearDirectory();clearView();}}}finally{if(current.active())busy.value=false;}}
async function load(id:string){selection.value++;const current=viewScope.begin('detail');busy.value=true;error.value='';clearView();try{const r=await api('/'+id+'?clinicId='+clinic.value,undefined,current);if(current())detail.value=r;}catch(e:any){if(current())error.value=e.message;}finally{if(current.active())busy.value=false;}}
function open(b:string){if(cacheBlocked.value||pending.value){error.value='请先核查原提交缓存，未打开新维护。';return;}const d=detail.value;let value:any;if(b==='identity')value={name:d.name,birthDate:d.profile.birthDate||'',phone:d.profile.phone||'',contactAddress:d.profile.contactAddress||'',billingAddress:d.profile.billingAddress||'',email:d.profile.email||''};else if(b==='source')value={sourceNote:d.profile.sourceNote||'',introducerNote:d.profile.introducerNote||''};else if(b==='contact')value={contactPreference:d.profile.contactPreference||'',channels:JSON.parse(JSON.stringify(d.profile.channels))};else if(b==='health')value={knowledge:d.health.knowledge,note:d.health.note||'',allergies:JSON.parse(JSON.stringify(d.health.allergies))};else value={tags:d.health.tags.join('\n')};data.value=value;branch.value=b;reason.value='';preview.value=null;checked.value=false;}
function payload(){const d=JSON.parse(JSON.stringify(data.value)),nullable=(v:any)=>typeof v==='string'&&!v.trim()?null:v;if(branch.value==='tags')d.tags=d.tags.split('\n').map((x:string)=>x.trim()).filter(Boolean);else for(const k of Object.keys(d))if(k!=='knowledge'&&k!=='name'&&!Array.isArray(d[k]))d[k]=nullable(d[k]);if(d.channels)for(const x of d.channels)x.note=nullable(x.note);if(d.allergies)for(const x of d.allergies)x.description=nullable(x.description);return{clinicId:clinic.value,version:detail.value.version,branch:branch.value,data:d,reason:reason.value};}
const previewCurrent=computed(()=>!!preview.value&&preview.value.signature===JSON.stringify(payload()));
async function inspect(){if(cacheBlocked.value||pending.value)return;const body=payload(),signature=JSON.stringify(body),current=viewScope.begin('preview',()=>JSON.stringify([detail.value?.id,branch.value,data.value,reason.value]));busy.value=true;error.value='';preview.value=null;checked.value=false;try{const r=await api('/'+detail.value.id+'/preview',body,current);if(current())preview.value={...r,signature};}catch(e:any){if(current()){preview.value=null;error.value=e.message;}}finally{if(current.active())busy.value=false;}}
async function submit(value:any,retry=false){if(busy.value||cacheBlocked.value)return;let p:any;try{p=patientCommand(value,props.staff);if(p.phase!=='pending'){error.value='原办理已有明确结果，请只清理提示。';return;}const raw=sessionStorage.getItem(cache());if(raw){const cached=parsePatientCommand(raw,props.staff);if(cached.phase!=='pending'||!samePatientCommand(cached,p))throw Error('本机已有另一笔或已完成的原请求，未重新发送。');}}catch(e:any){cacheBlocked.value=true;cacheError.value=e.message;return;}pending.value=p;try{keep();}catch{if(!retry)pending.value=null;error.value='本机未能保存原请求，本次没有发送；请恢复存储后再试。';return;}const current=authScope.begin('submit'),view=viewScope.capture();let committed=false;busy.value=true;error.value='';try{const r=await api('/'+p.id,p.body,current);if(!current())return;if(typeof r.id!=='string'||r.id.toLowerCase()!==p.id.toLowerCase()||r.version!==p.body.version+1||r.branch!==p.body.branch)throw Error('保存回复不完整，请保留原请求并只读核实。');committed=true;markKnown(p,'confirmed');clearDirectory();clearHistory();busy.value=false;cleanupKnown();busy.value=true;branch.value='';preview.value=null;notice.value='患者档案已保存。当前版本 '+r.version;const d=await api('/'+p.id+'?clinicId='+p.body.clinicId,undefined,()=>current()&&view());if(!current()||!view())return;detail.value=d;clearDirectory();clearHistory();}catch(e:any){if(!current())return;error.value=committed?'已保存，详情刷新未完成；请重新查询，勿重新办理。 '+e.message:e.message;if(committed){clearView();return;}if(!retry&&e.status&&e.status>=400&&e.status<500&&e.status!==401){markKnown(p,'rejected');busy.value=false;cleanupKnown();busy.value=true;}else{pending.value={...p,phase:'pending',uncertain:true};try{keep();}catch{cacheError.value='原请求仍保留在本页，但缓存更新失败；请勿另建相同办理。';}branch.value='';preview.value=null;}}finally{if(current.active())busy.value=false;}}

async function save(){if(cacheBlocked.value||busy.value||pending.value||!previewCurrent.value||!checked.value)return;try{if(sessionStorage.getItem(cache())){restoreCache();error.value='请先处理本机原提交记录，未发送新保存。';return;}}catch{cacheBlocked.value=true;cacheError.value='无法读取原提交缓存，未发送新保存。';return;}const p={id:detail.value.id,body:{...payload(),requestId:crypto.randomUUID(),previewToken:preview.value.previewToken,confirmed:true},uncertain:false};await submit(p);}

async function loadHistory(more=false){if(!detail.value||more&&!nextVersion.value)return;const current=viewScope.begin('history',()=>detail.value?.id||''),id=detail.value.id;busy.value=true;error.value='';if(!more)clearHistory();try{const r=await api('/'+id+'/history-page?clinicId='+clinic.value+(more?'&cursor='+encodeURIComponent(nextVersion.value!):''),undefined,current);if(current()){if(more&&r.asOf!==historyAsOf.value)throw Object.assign(Error('患者历史读取时点已变化，请重新打开历史。'),{status:409});history.value=more?[...history.value,...r.items]:r.items;nextVersion.value=r.next;historyTotal.value=r.total;historyAsOf.value=r.asOf;}}catch(e:any){if(current()){error.value=e.message;if([401,403,409].includes(e.status))clearHistory();}}finally{if(current.active())busy.value=false;}}
function show(k:string,v:any){if(v===null||v===undefined||v==='')return'未登记';if(k==='knowledge')return knowledge[v]||v;if(k==='allergies')return v.length?v.map((x:any)=>x.allergen+(x.description?'：'+x.description:'')).join('\n'):'无逐项记录';if(k==='channels')return v.length?v.map((x:any)=>x.name+(x.note?'：'+x.note:'')).join('\n'):'未登记';if(Array.isArray(v))return v.join('、')||'无已登记标签';return String(v);}
async function initialize(){const current=authScope.begin('initialize');busy.value=true;try{restoreCache();const r=await api('/bootstrap',undefined,current);if(!current())return;clinics.value=r.clinics;clinic.value=pending.value?.body.clinicId||r.clinics[0]?.id||'';}catch(e:any){if(current())error.value=e.message;}finally{if(current.active())busy.value=false;}if(current()&&clinic.value)await refresh();}onMounted(initialize);watch(identity,()=>{clinics.value=[];clinic.value='';query.value='';clearDirectory();clearView();pending.value=null;busy.value=false;error.value='';notice.value='';void initialize();},{flush:'sync'});defineExpose({refresh});
</script>
<template><section class="p-workspace"><div v-if="cacheError" class="b-alert error">{{cacheError}}<button type="button" class="b-button outline" :disabled="busy||commandBusy" @click="restoreCache">重新读取本机记录</button></div><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success">{{notice}}</div><div v-if="pending" class="b-alert warning"><template v-if="['confirmed','rejected'].includes(pending.phase)"><p>本机已记录原办理{{pending.phase==='confirmed'?'成功':'被拒绝'}}，只需清理提示，不会重新发送。</p><button type="button" class="b-button outline" :disabled="busy||commandBusy" @click="cleanupKnown">仅清理本机提示</button></template><template v-else><p>一笔档案保存结果待核实，请先只读查原请求。</p><button type="button" class="b-button outline" :disabled="busy||commandBusy" @click="checkPending">{{commandBusy?'正在核实…':'只读核实原保存'}}</button><template v-if="commandStatus?.state==='completed'"><p>已查到原保存：{{commandStatus.resultId}} · 第 {{commandStatus.version}} 版 · {{new Date(commandStatus.completedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}。此处是原结果，不是当前最新版本。</p><button type="button" class="b-button outline" :disabled="busy||commandBusy" @click="clearPending">已核对，清理本机提示</button></template><template v-else-if="commandStatus?.state==='not_found'"><p>暂未见原成功凭据，可能仍在处理或尚未提交，不能据此认定未保存。请核对后再决定是否沿原请求重试。</p><label><input type="checkbox" v-model="retryChecked" :disabled="busy||commandBusy"/>已核对，按原请求号和原内容重试</label><button type="button" class="b-button outline" :disabled="busy||commandBusy||!retryChecked" @click="retryPending">重试原保存</button></template></template></div><section class="b-card p-search"><div class="b-eyebrow">PATIENT RECORDS</div><h2><Users :size="22"/>患者档案</h2><p>核对同一患者身份，按职责补充资料，保留每次原版。</p><form class="p-filters" @submit.prevent="refresh()"><label>查询诊所<select v-model="clinic" :disabled="busy||!!pending" @change="refresh()"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>患者检索<input v-model="query" :disabled="busy||!!pending" placeholder="姓名；获授权前台也可按电话检索" maxlength="100"/></label><button class="b-button outline" :disabled="busy||!clinic||!!pending"><Search :size="17"/>检索患者</button></form><p class="b-help">新患者仍由前台在预约与接诊中核实建档；不凭同名或同号自动合并。</p></section><div class="p-layout"><aside class="b-card p-list"><h3>本诊所患者</h3><p v-if="directoryTotal!==null" class="b-help">已加载 {{rows.length}} / 共 {{directoryTotal}} 人</p><button v-for="p in rows" :key="p.id" class="p-patient" :class="{selected:detail?.id===p.id}" :disabled="busy||!!pending" @click="load(p.id)"><strong>{{p.name}}</strong><small v-if="p.phone">{{p.phone}}</small><small>{{p.id.slice(0,8).toUpperCase()}} · v{{p.version}}</small></button><p v-if="!rows.length">{{busy?'正在读取档案…':loadedQuery===null?'条件已变更，请检索患者。':'未找到匹配档案。'}}</p><button v-if="nextId" class="b-button outline" :disabled="busy||!!pending" @click="refresh(true)">继续加载患者</button></aside><div class="p-details" v-if="detail"><section class="b-card p-card"><div class="p-title"><div><h2>{{detail.name}}</h2><p>档案 {{detail.id.slice(0,8).toUpperCase()}} · v{{detail.version}}</p></div><span class="b-pill">{{detail.sharedClinicCount>1?'跨店共用档案':'本诊所档案'}}</span></div><p v-if="detail.sharedClinicCount>1" class="b-help">共用资料修改须具备全部关联诊所的对应权限。</p></section><template v-if="detail.profile"><section class="b-card p-card"><div class="p-title"><h3>基本资料</h3><button v-if="detail.canManage.identity" class="b-button outline" :disabled="busy||!!pending" @click="open('identity')">维护基本资料</button></div><dl class="p-fields"><div v-for="k in ['birthDate','phone','contactAddress','billingAddress','email']" :key="k"><dt>{{labels[k]}}</dt><dd>{{show(k,detail.profile[k])}}</dd></div></dl></section><section class="b-card p-card"><div class="p-title"><h3>患者来源</h3><button v-if="detail.canManage.source" class="b-button outline" :disabled="busy||!!pending" @click="open('source')">维护患者来源</button></div><p>{{detail.profile.sourceNote||'来源未明确'}}</p><p v-if="detail.profile.introducerNote">介绍人：{{detail.profile.introducerNote}}</p></section><section class="b-card p-card"><div class="p-title"><h3>联系要求与渠道</h3><button v-if="detail.canManage.contact" class="b-button outline" :disabled="busy||!!pending" @click="open('contact')">维护联系要求</button></div><p>{{detail.profile.contactPreference||'联系要求未登记'}}</p><div v-for="c in detail.profile.channels" :key="c.id" class="p-line"><strong>{{c.name}}</strong><p>{{c.note||'关联情况未登记'}}</p></div><p class="b-help">记录实际联系要求与关联情况，不发送消息或自动绑定身份。</p></section></template><template v-if="detail.health"><section class="b-card p-card"><div class="p-title"><h3>过敏信息</h3><button v-if="detail.canManage.health" class="b-button outline" :disabled="busy||!!pending" @click="open('health')">维护过敏信息</button></div><strong class="p-health-state">{{knowledge[detail.health.knowledge]}}</strong><div v-for="item in detail.health.allergies" :key="item.id" class="p-line"><strong>{{item.allergen}}</strong><p>{{item.description||'未附说明'}}</p></div><p v-if="detail.health.note">{{detail.health.note}}</p></section><section class="b-card p-card"><div class="p-title"><h3>患者标签</h3><button v-if="detail.canManage.tags" class="b-button outline" :disabled="busy||!!pending" @click="open('tags')">维护患者标签</button></div><div class="p-tags"><span class="b-pill" v-for="tag in detail.health.tags" :key="tag">{{tag}}</span><p v-if="!detail.health.tags.length">尚无已登记标签。</p></div></section></template><section class="b-card p-card"><div class="p-title"><h3>档案原版历史</h3><button class="b-button outline" :disabled="busy" @click="loadHistory()"><History :size="17"/>查看原版历史</button></div><p v-if="historyTotal!==null" class="b-help">已加载 {{history.length}} / 共 {{historyTotal}} 版<span v-if="historyTotal===0">，尚无已留存原版</span></p><article v-for="v in history" :key="v.version" class="p-line"><strong>原版 {{v.version}} · {{v.name}}</strong><small>{{v.editor}} · {{new Date(v.registeredAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}{{v.baselineCapture?' · 首次留存原资料':''}}</small><template v-if="v.profile"><p>{{v.profile.phone||'电话未登记'}} · {{v.profile.birthDate||'出生日期未登记'}}</p><p>{{v.profile.contactAddress||'联系地址未登记'}}；{{v.profile.billingAddress||'账单地址未登记'}}</p><p v-if="v.profile.email">邮箱：{{v.profile.email}}</p><p>{{v.profile.sourceNote||'来源未明确'}}；{{v.profile.introducerNote||'介绍人未登记'}}</p><p>{{v.profile.contactPreference||'联系要求未登记'}}</p><p v-for="c in v.profile.channels" :key="c.id">{{c.name}}：{{c.note||'未登记说明'}}</p></template><template v-if="v.health"><p>过敏：{{knowledge[v.health.knowledge]}}</p><p v-for="a in v.health.allergies" :key="a.id">{{a.allergen}}：{{a.description||'未附说明'}}</p><p v-if="v.health.note">{{v.health.note}}</p><p>标签：{{v.health.tags.join('、')||'无已登记标签'}}</p></template><p v-if="v.reason">依据：{{v.reason}}</p></article><button v-if="nextVersion" class="b-button outline" :disabled="busy" @click="loadHistory(true)">继续加载原版</button></section></div><section v-else class="b-card p-card p-empty"><ShieldCheck :size="30"/><h3>选择患者档案</h3><p>只显示当前诊所和岗位有权查看的内容。</p></section></div>
<div v-if="branch" class="b-backdrop"><form class="b-dialog p-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭患者档案维护" :disabled="busy||!!pending" @click="branch='' ;preview=null"><X :size="21"/></button><div class="b-eyebrow">PATIENT RECORD UPDATE</div><h2>{{names[branch]}} · {{detail?.name}}</h2><p>只保存本分支；其他资料和集合保留。</p><div v-if="error" class="b-alert error" role="alert">{{error}}</div><fieldset :disabled="busy||!!pending"><template v-if="branch==='identity'"><div class="b-two-fields"><label>姓名<input v-model="data.name" required maxlength="100"/></label><label>出生日期<input type="date" v-model="data.birthDate"/></label><label>联系电话<input v-model="data.phone" maxlength="40"/></label><label>电子邮箱<input type="email" v-model="data.email" maxlength="254"/></label></div><label>联系地址<textarea v-model="data.contactAddress" rows="2" maxlength="2000"/></label><label>账单地址<textarea v-model="data.billingAddress" rows="2" maxlength="2000"/></label></template><template v-if="branch==='source'"><label>患者提供的来源<textarea v-model="data.sourceNote" rows="3" maxlength="2000"/></label><label>介绍人说明<textarea v-model="data.introducerNote" rows="2" maxlength="2000"/></label><p class="b-help">不清楚时保留未明确，不由工作人员推测。</p></template><template v-if="branch==='contact'"><label>联系要求<textarea v-model="data.contactPreference" rows="3" maxlength="2000"/></label><div v-for="(c,i) in data.channels" :key="c.id" class="p-edit-row"><label>渠道名称<input v-model="c.name" required maxlength="100"/></label><label>关联情况<textarea v-model="c.note" rows="2" maxlength="2000"/></label></div><button type="button" class="b-button outline" :disabled="data.channels.length>=50" @click="addChannel"><Plus :size="16"/>增加沟通渠道</button><p class="b-help">原渠道保留身份；已解除关联的渠道请在说明中据实记录。</p></template><template v-if="branch==='health'"><label>过敏了解状态<select v-model="data.knowledge"><option value="unknown">尚未了解</option><option value="none_reported">患者表示无已知过敏</option><option value="reported">已报告具体过敏</option></select></label><div v-for="(a,i) in data.allergies" :key="a.id" class="p-edit-row"><label>过敏对象<input v-model="a.allergen" required maxlength="200"/></label><label>该项说明<textarea v-model="a.description" rows="2" maxlength="2000"/></label><button type="button" class="f-text" @click="data.allergies.splice(i,1)">本版移除此项</button></div><button type="button" class="b-button outline" :disabled="data.allergies.length>=50" @click="addAllergy"><Plus :size="16"/>增加过敏条目</button><label>过敏备注<textarea v-model="data.note" rows="2" maxlength="2000"/></label><p class="b-help">逐项记录实际报告和核对依据，未知不能记为无过敏。</p></template><template v-if="branch==='tags'"><label>患者标签（每行一个）<textarea v-model="data.tags" rows="5"/></label><p class="b-help">最多50项，按实际需要填写，不以标签代替诊疗结论。</p></template><label>本次核实依据<textarea v-model="reason" required rows="2" maxlength="2000"/></label></fieldset><button type="button" class="b-button outline full" :disabled="busy||!!pending||cacheBlocked||!reason.trim()" @click="inspect">核对本次档案修改</button><div v-if="previewCurrent" class="p-preview"><h3>核对{{names[branch]}}</h3><div v-for="k in Object.keys(preview.after)" :key="k" class="p-compare"><strong>{{labels[k]}}</strong><div><small>修改前</small><p>{{show(k,preview.before[k])}}</p></div><div><small>修改后</small><p>{{show(k,preview.after[k])}}</p></div></div><label class="b-checkbox"><input type="checkbox" v-model="checked" :disabled="busy||!!pending"/><span>已核对患者身份及本次内容，确认另存新版本。</span></label></div><button class="b-button full" :disabled="busy||!!pending||cacheBlocked||!previewCurrent||!checked"><Save :size="17"/>确认保存患者档案</button></form></div></section></template>
<style scoped>.p-workspace{min-width:0}.p-search,.p-card{padding:26px;margin-bottom:20px}.p-search h2{display:flex;align-items:center;gap:9px}.p-search p,.p-card>p{color:#718174;font-size:14px;line-height:1.9;white-space:pre-wrap}.p-filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin:22px 0}.p-filters label{display:grid;gap:8px;min-width:180px;flex:1;font-size:13px}.p-filters input,.p-filters select,.p-dialog input:not([type=checkbox]),.p-dialog textarea,.p-dialog select{width:100%;box-sizing:border-box;min-width:0;border:1px solid #dce5d8;border-radius:8px;background:white;padding:11px;font:inherit}.p-layout{display:grid;grid-template-columns:245px minmax(0,1fr);gap:20px;align-items:start}.p-list{padding:22px;min-width:0}.p-patient{width:100%;display:grid;gap:7px;text-align:left;padding:16px;border-radius:8px;border:1px solid #e4ebe1;margin:12px 0;overflow-wrap:anywhere}.p-patient.selected{background:#edf5e9;border-color:#a4bda2}.p-patient small,.p-line small{display:block;font-size:12px;color:#7d8c7d;line-height:1.8}.p-details{min-width:0}.p-title{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.p-title h2,.p-title h3{margin:0}.p-title p{font-size:12px;color:#7b8b7d}.p-fields{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:22px}.p-fields dt{font-size:12px;color:#809080}.p-fields dd{margin:10px 0 0;line-height:1.8;overflow-wrap:anywhere;white-space:pre-wrap}.p-line{padding:18px 0;border-top:1px solid #e5ebe2;margin-top:15px}.p-line p{font-size:14px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.p-health-state{display:block;padding:16px 0;color:#3f6651}.p-tags{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.p-empty{text-align:center;padding-top:50px;padding-bottom:50px;color:#7d9381}.p-dialog.b-dialog{width:min(760px,calc(100vw - 36px));max-width:760px}.p-dialog fieldset{border:0;min-width:0;padding:0;margin:0}.p-dialog label{display:grid;gap:8px;margin:18px 0;font-size:14px}.p-dialog label.b-checkbox{display:flex;align-items:start;line-height:1.8}.p-edit-row,.p-preview{padding:18px;border-radius:10px;background:#f3f7ef;margin:20px 0}.p-compare{display:grid;grid-template-columns:1fr 1fr;gap:14px;border-top:1px solid #dfe8d9;padding:15px 0;min-width:0}.p-compare>strong{grid-column:1/-1}.p-compare p{font-size:13px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.p-compare small{color:#7b8e77}.p-dialog .b-help{font-size:12px;line-height:1.8}@media(max-width:850px){.p-layout{grid-template-columns:minmax(0,1fr)}.p-list{display:grid;grid-template-columns:1fr 1fr;gap:10px}.p-list h3,.p-list>.b-help,.p-list>p{grid-column:1/-1}.p-patient{margin:0}}@media(max-width:600px){.p-card,.p-search,.p-list{padding:18px}.p-fields{grid-template-columns:minmax(0,1fr)}.p-filters label{min-width:0;flex-basis:100%}.p-title>.b-button{width:100%}.p-compare{grid-template-columns:minmax(0,1fr)}.p-compare>strong{grid-column:auto}.p-list{grid-template-columns:minmax(0,1fr)}}</style>
